import{_ as l,o as e,c as i,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"模组开发规范","description":"","frontmatter":{"title":"模组开发规范","order":24},"headers":[],"relativePath":"zh/learn/mod/guidelines.md","filePath":"zh/learn/mod/guidelines.md","lastUpdated":1786943111000}'),t={name:"zh/learn/mod/guidelines.md"};function r(s,a,n,d,c,h){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="模组开发规范" tabindex="-1">模组开发规范 <a class="header-anchor" href="#模组开发规范" aria-label="Permalink to &quot;模组开发规范&quot;">​</a></h1><p>在发布你的 Mod 之前，请阅读并遵守以下规范。它们保护玩家、保护开发者、也保护这个生态。</p><h2 id="_1-不要破坏原版游戏平衡" tabindex="-1">1. 不要破坏原版游戏平衡 <a class="header-anchor" href="#_1-不要破坏原版游戏平衡" aria-label="Permalink to &quot;1. 不要破坏原版游戏平衡&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">红线</p><p>请勿制作<strong>脱离原版游戏平衡</strong>的 Mod，例如改动判定、精度计算、伤害数值等影响游戏核心体验的内容。游戏判定是官方的雷区。</p></div><ul><li>本教程<strong>不会</strong>介绍修改判定的做法，也请勿在任何渠道宣传这类功能</li><li>如果想让玩家获得更好的成绩展示，请参考组织内的 <a href="./../../mods/not-enough-accuracy">NotEnoughAccuracy</a>、<a href="./../../mods/just-enough-accuracy">JustEnoughAccuracy</a> 这类<strong>不影响原版判定</strong>的精度统计方案</li></ul><h2 id="_2-ai-生成内容需要注明" tabindex="-1">2. AI 生成内容需要注明 <a class="header-anchor" href="#_2-ai-生成内容需要注明" aria-label="Permalink to &quot;2. AI 生成内容需要注明&quot;">​</a></h2><p>如果你使用 AI 生成了代码、文档或素材，请在仓库中注明。</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 本模块由 AI 辅助生成（[工具/模型名]），使用前请人工审查 --&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>为什么：</p><ul><li>保证代码质量与可信度</li><li>尊重贡献者与使用者</li><li>组织生态讲究透明与信任</li></ul><h2 id="_3-不要锁定关卡内容" tabindex="-1">3. 不要锁定关卡内容 <a class="header-anchor" href="#_3-不要锁定关卡内容" aria-label="Permalink to &quot;3. 不要锁定关卡内容&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>你不能将关卡或其他内容标记为「必须使用你的 Mod 才能打开」。</p></div><ul><li>关卡文件本身属于创作者，不应被某个 Mod 绑架</li><li>你的 Mod 可以<strong>增强</strong>体验，但不能<strong>绑架</strong>内容</li><li>发布到 modrift.org 的 Mod 也遵循同样的原则</li></ul><h2 id="_4-不要分发原版游戏二进制" tabindex="-1">4. 不要分发原版游戏二进制 <a class="header-anchor" href="#_4-不要分发原版游戏二进制" aria-label="Permalink to &quot;4. 不要分发原版游戏二进制&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Mod 产物与源代码仓库<strong>不得存放原版游戏的二进制文件</strong>（<code>Assembly-CSharp.dll</code>、<code>UnityEngine.dll</code> 等），它们受版权保护。</p></div><ul><li>编译时需要引用的原版 DLL，使用<strong>私有 lib 仓库</strong>方案（见 <a href="./github-actions">GitHub Actions 自动构建</a>）</li><li>构建产物（Release 的 zip）里只放你的 Mod 文件，不要附带游戏 DLL</li><li>反编译游戏二进制仅供理解与调试，不要外发</li></ul><h2 id="_5-其它质量要求" tabindex="-1">5. 其它质量要求 <a class="header-anchor" href="#_5-其它质量要求" aria-label="Permalink to &quot;5. 其它质量要求&quot;">​</a></h2><ul><li><strong>测试</strong>：功能需经过测试，发布前在干净环境下验证</li><li><strong>注释</strong>：代码包含良好注释（尤其是 AI 生成的部分）</li><li><strong>数据安全</strong>：持久化数据存放于 Mod 的本地配置目录，防止更新被覆盖</li><li><strong>健壮性</strong>：良好的错误处理机制，不要让 Mod 因一个错误而崩溃（可以参考 <a href="./harmony-finalizer">Finalizer 补丁</a>）</li><li><strong>协作</strong>：如果是扩展现有 Mod 的功能，优先向原项目提交 PR</li></ul><h2 id="你学到了什么" tabindex="-1">你学到了什么 <a class="header-anchor" href="#你学到了什么" aria-label="Permalink to &quot;你学到了什么&quot;">​</a></h2><ul><li>四条不可逾越的红线（平衡 / AI 注明 / 不锁定内容 / 不含二进制）</li><li>质量与协作的基本要求</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>遇到问题？看看 <a href="./troubleshooting">常见问题与排查</a></p>',22)])])}const g=l(t,[["render",r]]);export{p as __pageData,g as default};
